def alice_wins_color_removal(colors):
    alice=bob=0;run=1
    for index in range(1,len(colors)+1):
        if index<len(colors) and colors[index]==colors[index-1]:run+=1
        else:
            if colors[index-1]=='A':alice+=max(0,run-2)
            else:bob+=max(0,run-2)
            run=1
    return alice>bob

